(async function(){const $=id=>document.getElementById(id),invoke=(c,a={})=>window.__TAURI__.core.invoke(c,a);await WhaleXDB.initDb();const libs=await WhaleXDB.listLibraries();$('library').innerHTML=libs.map(l=>`<option>${l.name}</option>`).join('');$('closeBtn').onclick=()=>invoke('hide_capture');document.addEventListener('keydown',e=>{if(e.key==='Escape')invoke('hide_capture');if((e.ctrlKey||e.metaKey)&&e.key==='Enter')$('saveBtn').click()});$('saveBtn').onclick=async()=>{const content=$('content').value.trim(),title=$('title').value.trim()||(content?content.slice(0,32):'Untitled');if(!content&&!$('title').value.trim())return;const n=await WhaleXDB.createNote({title,content,library:$('library').value,type:$('type').value,tags:$('tags').value.split(/[\s,]+/).map(x=>x.replace(/^#/,'')).filter(Boolean),sticky:$('sticky').checked,color:['blue','purple','green','yellow'][Math.floor(Math.random()*4)]});if(n.sticky)await invoke('open_sticky',{id:n.id});await WhaleXDB.notify();$('title').value='';$('content').value='';$('tags').value='';$('sticky').checked=false;await invoke('hide_capture')}})();